import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';

export const CLI_PATH = path.resolve(import.meta.dirname, '..', '..', 'jsonpatch-cli.mjs');
export const USAGE_LINE = 'Usage: node jsonpatch-cli.mjs <patch> [<doc>]';
export const MAX_BYTES = 1048576;
export const BOM = Buffer.from([0xef, 0xbb, 0xbf]);

export function run(args, { input, stdio, cwd } = {}) {
  const options = { cwd, maxBuffer: 256 * 1024 * 1024 };
  if (stdio !== undefined) options.stdio = stdio;
  else if (input !== undefined) options.input = input;
  const res = spawnSync(process.execPath, [CLI_PATH, ...args], options);
  assert.equal(res.error, undefined, 'spawn failed');
  return {
    status: res.status,
    stdout: res.stdout.toString('utf8'),
    stderr: res.stderr.toString('utf8'),
  };
}

// Exact string equality; skips assert's diff for big strings, which can take
// minutes on ~1 MB outputs and makes a failing run look hung.
const DIFF_LIMIT = 4096;
function assertSameText(actual, expected, label) {
  if (actual.length <= DIFF_LIMIT && expected.length <= DIFF_LIMIT) {
    assert.strictEqual(actual, expected, label);
    return;
  }
  let at = 0;
  while (at < actual.length && actual[at] === expected[at]) at += 1;
  assert.ok(actual === expected,
    `${label}: lengths ${actual.length} vs ${expected.length}, first difference at ${at}`);
}

export function expectError(result, line, code) {
  assertSameText(result.stderr, `${line}\n`, 'stderr');
  assertSameText(result.stdout, '', 'stdout');
  assert.strictEqual(result.status, code);
}

export function expectOk(result, expectedStdout) {
  assertSameText(result.stderr, '', 'stderr');
  assertSameText(result.stdout, expectedStdout, 'stdout');
  assert.strictEqual(result.status, 0);
}

export function makeTmpDir() {
  return fs.mkdtempSync(path.join(os.tmpdir(), 'jp-cli-'));
}

export function removeTmpDir(dir) {
  fs.rmSync(dir, { recursive: true, force: true });
}

export function writeIn(dir, name, content) {
  const file = path.join(dir, name);
  fs.writeFileSync(file, content);
  return file;
}

// Valid JSON "[]" followed by spaces, exactly `size` bytes.
export function paddedJson(size) {
  return Buffer.concat([Buffer.from('[]'), Buffer.alloc(size - 2, 0x20)]);
}
import { after, before, describe, test } from 'node:test';
import assert from 'node:assert/strict';
import path from 'node:path';
import {
  BOM,
  USAGE_LINE,
  expectError,
  expectOk,
  makeTmpDir,
  paddedJson,
  removeTmpDir,
  run,
  writeIn,
} from './helpers/cli-runner.mjs';

let dir;
let f;

before(() => {
  dir = makeTmpDir();
  f = (name) => path.join(dir, name);
});

after(() => {
  removeTmpDir(dir);
});

const ADD_B = '[{"op":"add","path":"/b","value":[1,{"c":null}]}]';
const ADD_B_OUT = '{\n  "a": 1,\n  "b": [\n    1,\n    {\n      "c": null\n    }\n  ]\n}\n';
const deepArr = (n) => '['.repeat(n) + ']'.repeat(n);
const deepObj = (n) => '{"a":'.repeat(n) + '1' + '}'.repeat(n);

describe('usage', () => {
  test('0 args', () => {
    expectError(run([]), USAGE_LINE, 2);
  });
  test('3 args', () => {
    expectError(run(['a', 'b', 'c']), USAGE_LINE, 2);
  });
  test('3 args with nonexistent files is usage, not no such file', () => {
    expectError(run([f('x1.json'), f('x2.json'), f('x3.json')]), USAGE_LINE, 2);
  });
  test('single "-" (both stdin)', () => {
    expectError(run(['-'], { input: '[]' }), USAGE_LINE, 2);
  });
  test('"-" "-"', () => {
    expectError(run(['-', '-'], { input: '[]' }), USAGE_LINE, 2);
  });
});

describe('success', () => {
  test('patch file + doc file', () => {
    const p = writeIn(dir, 'p1.json', ADD_B);
    const d = writeIn(dir, 'd1.json', '{"a":1}');
    expectOk(run([p, d]), ADD_B_OUT);
  });
  test('patch file + doc via stdin (one arg)', () => {
    const p = writeIn(dir, 'p2.json', ADD_B);
    expectOk(run([p], { input: '{"a":1}' }), ADD_B_OUT);
  });
  test('patch file + "-" doc via stdin', () => {
    const p = writeIn(dir, 'p3.json', ADD_B);
    expectOk(run([p, '-'], { input: '{"a":1}' }), ADD_B_OUT);
  });
  test('patch "-" via stdin + doc file', () => {
    const d = writeIn(dir, 'd4.json', '{"a":1}');
    expectOk(run(['-', d], { input: ADD_B }), ADD_B_OUT);
  });
  test('scalar result', () => {
    const p = writeIn(dir, 'p5.json', '[{"op":"replace","path":"","value":"x"}]');
    const d = writeIn(dir, 'd5.json', '{"a":1}');
    expectOk(run([p, d]), '"x"\n');
  });
  test('scalar doc with empty patch', () => {
    const p = writeIn(dir, 'p6.json', '[]');
    const d = writeIn(dir, 'd6.json', '5');
    expectOk(run([p, d]), '5\n');
  });
  test('empty array doc with empty patch', () => {
    const p = writeIn(dir, 'p7.json', '[]');
    const d = writeIn(dir, 'd7.json', '[]');
    expectOk(run([p, d]), '[]\n');
  });
  test('non-ASCII value round-trips as raw UTF-8', () => {
    const p = writeIn(dir, 'p8.json', '[{"op":"add","path":"/s","value":"é€😀"}]');
    const d = writeIn(dir, 'd8.json', '{}');
    expectOk(run([p, d]), '{\n  "s": "é€😀"\n}\n');
  });
  test('non-ASCII value in doc round-trips', () => {
    const p = writeIn(dir, 'p9.json', '[]');
    const d = writeIn(dir, 'd9.json', '["é€😀"]');
    expectOk(run([p, d]), '[\n  "é€😀"\n]\n');
  });
});

describe('BOM and encoding', () => {
  test('BOM before patch JSON is ignored', () => {
    const p = writeIn(dir, 'bp.json', Buffer.concat([BOM, Buffer.from('[]')]));
    const d = writeIn(dir, 'bd.json', '[1]');
    expectOk(run([p, d]), '[\n  1\n]\n');
  });
  test('BOM before doc JSON is ignored', () => {
    const p = writeIn(dir, 'bp2.json', '[]');
    const d = writeIn(dir, 'bd2.json', Buffer.concat([BOM, Buffer.from('[1]')]));
    expectOk(run([p, d]), '[\n  1\n]\n');
  });
  test('BOM not at start (after whitespace) is invalid JSON', () => {
    const p = writeIn(dir, 'bp3.json', Buffer.concat([Buffer.from(' '), BOM, Buffer.from('[]')]));
    expectError(run([p, f('none.json')]), `Error: ${p}: invalid JSON`, 3);
  });
  test('double BOM is invalid JSON', () => {
    const p = writeIn(dir, 'bp4.json', Buffer.concat([BOM, BOM, Buffer.from('[]')]));
    expectError(run([p, f('none.json')]), `Error: ${p}: invalid JSON`, 3);
  });
  test('UTF-16LE BOM is invalid UTF-8', () => {
    const p = writeIn(dir, 'bp5.json', Buffer.from([0xff, 0xfe, 0x5b, 0x00, 0x5d, 0x00]));
    expectError(run([p, f('none.json')]), `Error: ${p}: invalid UTF-8`, 3);
  });
});

describe('invalid UTF-8', () => {
  const cases = {
    'C3 28': Buffer.from([0xc3, 0x28]),
    'lone FF': Buffer.from([0xff]),
    'overlong C0 AF': Buffer.from([0xc0, 0xaf]),
    'encoded surrogate ED A0 80 in string': Buffer.concat([
      Buffer.from('["'),
      Buffer.from([0xed, 0xa0, 0x80]),
      Buffer.from('"]'),
    ]),
  };
  for (const [label, bytes] of Object.entries(cases)) {
    test(`patch: ${label}`, () => {
      const p = writeIn(dir, 'u-p.json', bytes);
      expectError(run([p, f('none.json')]), `Error: ${p}: invalid UTF-8`, 3);
    });
    test(`doc: ${label}`, () => {
      const p = writeIn(dir, 'u-pp.json', '[]');
      const d = writeIn(dir, 'u-d.json', bytes);
      expectError(run([p, d]), `Error: ${d}: invalid UTF-8`, 3);
    });
  }
  test('stdin doc invalid UTF-8 names stdin', () => {
    const p = writeIn(dir, 'u-ps.json', '[]');
    expectError(run([p], { input: Buffer.from([0xff]) }), 'Error: stdin: invalid UTF-8', 3);
  });
});

describe('invalid JSON', () => {
  const cases = {
    empty: '',
    'whitespace only': ' \n\t ',
    'BOM only': BOM,
    '{a:1}': '{a:1}',
    'trailing comma': '[1,]',
    NaN: 'NaN',
  };
  for (const [label, content] of Object.entries(cases)) {
    test(`patch: ${label}`, () => {
      const p = writeIn(dir, 'j-p.json', content);
      expectError(run([p, f('none.json')]), `Error: ${p}: invalid JSON`, 3);
    });
    test(`doc: ${label}`, () => {
      const p = writeIn(dir, 'j-pp.json', '[]');
      const d = writeIn(dir, 'j-d.json', content);
      expectError(run([p, d]), `Error: ${d}: invalid JSON`, 3);
    });
  }
  test('stdin patch invalid JSON names stdin', () => {
    const d = writeIn(dir, 'j-ds.json', '{}');
    expectError(run(['-', d], { input: '{a:1}' }), 'Error: stdin: invalid JSON', 3);
  });
  test('empty stdin doc names stdin', () => {
    const p = writeIn(dir, 'j-ps.json', '[]');
    expectError(run([p], { input: '' }), 'Error: stdin: invalid JSON', 3);
  });
});

describe('depth', () => {
  test('patch depth 1000 passes depth check (PatchError later)', () => {
    const p = writeIn(dir, 'dp1000.json', deepArr(1000));
    const d = writeIn(dir, 'dd.json', '{}');
    expectError(run([p, d]), 'Error: operation 0: not an object', 4);
  });
  test('patch depth 1001 is too deep', () => {
    const p = writeIn(dir, 'dp1001.json', deepArr(1001));
    const d = writeIn(dir, 'dd2.json', '{}');
    expectError(run([p, d]), `Error: ${p}: too deep`, 3);
  });
  test('doc array depth 1000 is OK', () => {
    const p = writeIn(dir, 'dp0.json', '[]');
    const d = writeIn(dir, 'dd1000.json', deepArr(1000));
    expectOk(run([p, d]), `${JSON.stringify(JSON.parse(deepArr(1000)), null, 2)}\n`);
  });
  test('doc array depth 1001 is too deep', () => {
    const p = writeIn(dir, 'dp0b.json', '[]');
    const d = writeIn(dir, 'dd1001.json', deepArr(1001));
    expectError(run([p, d]), `Error: ${d}: too deep`, 3);
  });
  test('doc mixed object depth 1000 is OK', () => {
    const p = writeIn(dir, 'dp0c.json', '[]');
    const d = writeIn(dir, 'ddo1000.json', deepObj(1000));
    expectOk(run([p, d]), `${JSON.stringify(JSON.parse(deepObj(1000)), null, 2)}\n`);
  });
  test('doc mixed object depth 1001 is too deep', () => {
    const p = writeIn(dir, 'dp0d.json', '[]');
    const d = writeIn(dir, 'ddo1001.json', deepObj(1001));
    expectError(run([p, d]), `Error: ${d}: too deep`, 3);
  });
  test('stdin doc too deep names stdin', () => {
    const p = writeIn(dir, 'dp0e.json', '[]');
    expectError(run([p], { input: deepArr(1001) }), 'Error: stdin: too deep', 3);
  });
  test('stdin patch too deep names stdin', () => {
    const d = writeIn(dir, 'dd3.json', '{}');
    expectError(run(['-', d], { input: deepArr(1001) }), 'Error: stdin: too deep', 3);
  });
});

describe('PatchError', () => {
  test('patch is not an array', () => {
    const p = writeIn(dir, 'e1.json', '{}');
    const d = writeIn(dir, 'e1d.json', '{}');
    expectError(run([p, d]), 'Error: patch must be an array', 4);
  });
  test('test op failure', () => {
    const p = writeIn(dir, 'e2.json', '[{"op":"test","path":"/a","value":2}]');
    const d = writeIn(dir, 'e2d.json', '{"a":1}');
    expectError(run([p, d]), 'Error: operation 0: test failed', 4);
  });
  test('bad op', () => {
    const p = writeIn(dir, 'e3.json', '[{"op":"x"}]');
    const d = writeIn(dir, 'e3d.json', '{}');
    expectError(run([p, d]), 'Error: operation 0: bad op', 4);
  });
});

describe('order of checks', () => {
  const badJson = () => writeIn(dir, 'o-bad.json', '{a:1}');
  test('invalid JSON patch + nonexistent doc -> patch error', () => {
    const p = badJson();
    expectError(run([p, f('missing.json')]), `Error: ${p}: invalid JSON`, 3);
  });
  test('missing patch + missing doc -> patch no such file', () => {
    const p = f('missing-p.json');
    expectError(run([p, f('missing-d.json')]), `Error: ${p}: no such file`, 1);
  });
  test('invalid UTF-8 patch + directory doc -> patch error', () => {
    const p = writeIn(dir, 'o-u.json', Buffer.from([0xff]));
    expectError(run([p, dir]), `Error: ${p}: invalid UTF-8`, 3);
  });
  test('too-deep patch + too-large doc -> patch too deep', () => {
    const p = writeIn(dir, 'o-deep.json', deepArr(1001));
    const d = writeIn(dir, 'o-large.json', paddedJson(1048577));
    expectError(run([p, d]), `Error: ${p}: too deep`, 3);
  });
  test('valid patch + missing doc -> doc no such file', () => {
    const p = writeIn(dir, 'o-ok.json', '[]');
    const d = f('o-missing.json');
    expectError(run([p, d]), `Error: ${d}: no such file`, 1);
  });
  test('valid patch + invalid JSON doc -> doc error', () => {
    const p = writeIn(dir, 'o-ok2.json', '[]');
    const d = badJson();
    expectError(run([p, d]), `Error: ${d}: invalid JSON`, 3);
  });
  test('PatchError patch + invalid JSON doc -> doc error (apply is last)', () => {
    const p = writeIn(dir, 'o-notarr.json', '{}');
    const d = badJson();
    expectError(run([p, d]), `Error: ${d}: invalid JSON`, 3);
  });
  test('invalid patch file + invalid stdin doc -> patch error', () => {
    const p = badJson();
    expectError(run([p], { input: '{a:1}' }), `Error: ${p}: invalid JSON`, 3);
  });
  test('patch [] from stdin + missing doc -> doc no such file', () => {
    const d = f('o-missing2.json');
    expectError(run(['-', d], { input: '[]' }), `Error: ${d}: no such file`, 1);
  });
});

describe('names as given', () => {
  test('relative name resolved against cwd', () => {
    expectError(run(['nope.json'], { cwd: dir }), 'Error: nope.json: no such file', 1);
  });
  test('path with ./ segment is echoed verbatim', () => {
    const p = `${dir}/./nope.json`;
    expectError(run([p]), `Error: ${p}: no such file`, 1);
  });
  test('non-ASCII file name is echoed verbatim', () => {
    const p = path.join(dir, 'ñ.json');
    expectError(run([p]), `Error: ${p}: no such file`, 1);
  });
  test('relative doc name', () => {
    writeIn(dir, 'rel-p.json', '[]');
    expectError(run(['rel-p.json', 'rel-d.json'], { cwd: dir }), 'Error: rel-d.json: no such file', 1);
  });
});
import { after, before, describe, test } from 'node:test';
import fs from 'node:fs';
import path from 'node:path';
import {
  BOM,
  MAX_BYTES,
  expectError,
  expectOk,
  makeTmpDir,
  paddedJson,
  removeTmpDir,
  run,
  writeIn,
} from './helpers/cli-runner.mjs';

let dir;
let lockedDir;

before(() => {
  dir = makeTmpDir();
});

after(() => {
  if (lockedDir) fs.chmodSync(lockedDir, 0o755);
  removeTmpDir(dir);
});

describe('read errors', () => {
  test('ENOENT', () => {
    const p = path.join(dir, 'nope.json');
    expectError(run([p]), `Error: ${p}: no such file`, 1);
  });
  test('ENOENT for doc', () => {
    const p = writeIn(dir, 'r-p.json', '[]');
    const d = path.join(dir, 'nope-doc.json');
    expectError(run([p, d]), `Error: ${d}: no such file`, 1);
  });
  test('ENOTDIR', () => {
    const file = writeIn(dir, 'r-file.txt', '[]');
    const p = `${file}/x`;
    expectError(run([p]), `Error: ${p}: no such file`, 1);
  });
  test('directory as patch', () => {
    expectError(run([dir]), `Error: ${dir}: is a directory`, 1);
  });
  test('directory as doc', () => {
    const p = writeIn(dir, 'r-p2.json', '[]');
    expectError(run([p, dir]), `Error: ${dir}: is a directory`, 1);
  });
  test('directory with mode 000', () => {
    lockedDir = path.join(dir, 'locked');
    fs.mkdirSync(lockedDir);
    fs.chmodSync(lockedDir, 0o000);
    expectError(run([lockedDir]), `Error: ${lockedDir}: is a directory`, 1);
    fs.chmodSync(lockedDir, 0o755);
  });
  test('symlink loop is cannot read', () => {
    const loop = path.join(dir, 'loop');
    fs.symlinkSync('loop', loop);
    expectError(run([loop]), `Error: ${loop}: cannot read`, 1);
  });
  test('300-char file name is cannot read', () => {
    const p = path.join(dir, 'a'.repeat(300));
    expectError(run([p]), `Error: ${p}: cannot read`, 1);
  });
});

describe('size boundary', () => {
  test('exactly 1048576 bytes patch is OK', () => {
    const p = writeIn(dir, 's-p.json', paddedJson(MAX_BYTES));
    const d = writeIn(dir, 's-d.json', '[1]');
    expectOk(run([p, d]), '[\n  1\n]\n');
  });
  test('1048577 bytes patch is too large', () => {
    const p = writeIn(dir, 's-p2.json', paddedJson(MAX_BYTES + 1));
    expectError(run([p, path.join(dir, 'x')]), `Error: ${p}: too large`, 1);
  });
  test('exactly 1048576 bytes doc is OK', () => {
    const p = writeIn(dir, 's-p3.json', '[]');
    const d = writeIn(dir, 's-d3.json', paddedJson(MAX_BYTES));
    expectOk(run([p, d]), '[]\n');
  });
  test('1048577 bytes doc is too large', () => {
    const p = writeIn(dir, 's-p4.json', '[]');
    const d = writeIn(dir, 's-d4.json', paddedJson(MAX_BYTES + 1));
    expectError(run([p, d]), `Error: ${d}: too large`, 1);
  });
  test('BOM + 1048574 bytes (total 1048577) is too large', () => {
    const p = writeIn(dir, 's-p5.json', Buffer.concat([BOM, paddedJson(MAX_BYTES - 2)]));
    expectError(run([p, path.join(dir, 'x')]), `Error: ${p}: too large`, 1);
  });
  test('BOM + 1048573 bytes (total 1048576) is OK', () => {
    const p = writeIn(dir, 's-p6.json', Buffer.concat([BOM, paddedJson(MAX_BYTES - 3)]));
    const d = writeIn(dir, 's-d6.json', '[1]');
    expectOk(run([p, d]), '[\n  1\n]\n');
  });
  test('/dev/zero as patch is too large (bytes read, not stat size)', () => {
    expectError(run(['/dev/zero']), 'Error: /dev/zero: too large', 1);
  });
});

describe('stdin', () => {
  test('stdin over limit is too large', () => {
    const p = writeIn(dir, 'i-p.json', '[]');
    const input = Buffer.alloc(MAX_BYTES + 1, 0x20);
    expectError(run([p], { input }), 'Error: stdin: too large', 1);
  });
  test('stdin exactly at limit is OK', () => {
    const p = writeIn(dir, 'i-p2.json', '[]');
    expectOk(run([p], { input: paddedJson(MAX_BYTES) }), '[]\n');
  });
  test('stdin patch over limit is too large', () => {
    const d = writeIn(dir, 'i-d.json', '{}');
    const input = Buffer.alloc(MAX_BYTES + 1, 0x20);
    expectError(run(['-', d], { input }), 'Error: stdin: too large', 1);
  });
  // Known CLI bug, reported to the supervisor: Node's process.stdin stream ends
  // silently on EISDIR, so readStdin() (jsonpatch-cli.mjs:59-79) yields 0 bytes
  // and the CLI prints "invalid JSON" (exit 3). Remove `todo` once fixed.
  test('stdin that is a directory is cannot read', {
    todo: 'jsonpatch-cli.mjs:59-79 reports invalid JSON for a directory on stdin',
  }, () => {
    const p = writeIn(dir, 'i-p3.json', '[]');
    const fd = fs.openSync(dir, 'r');
    try {
      expectError(run([p], { stdio: [fd, 'pipe', 'pipe'] }), 'Error: stdin: cannot read', 1);
    } finally {
      fs.closeSync(fd);
    }
  });
});

import { describe, test } from 'node:test';
import assert from 'node:assert/strict';
import { parsePointer, applyPatch, PatchError } from '../jsonpatch.mjs';

const invalid = { name: 'SyntaxError', message: 'invalid pointer' };

function check(doc, path, value = 1) {
  return applyPatch(doc, [{ op: 'test', path, value }]);
}

function failure(doc, path) {
  try {
    check(doc, path);
  } catch (err) {
    return err;
  }
  return assert.fail(`expected throw for ${JSON.stringify(path)}`);
}

describe('parsePointer valid', () => {
  const cases = [
    ['', []],
    ['/', ['']],
    ['/a//b/', ['a', '', 'b', '']],
    ['/~01', ['~1']],
    ['/~10', ['/0']],
    ['/a~1b/~0c', ['a/b', '~c']],
    ['/~0~1', ['~/']],
    ['/ é/ü', [' é', 'ü']],
    ['/é', ['é']],
    ['/a\nb', ['a\nb']],
  ];
  for (const [input, expected] of cases) {
    test(`parses ${JSON.stringify(input)}`, () => {
      assert.deepStrictEqual(parsePointer(input), expected);
    });
  }

  test('"/~01" is not decoded as "/"', () => {
    assert.notDeepStrictEqual(parsePointer('/~01'), ['/']);
    assert.deepStrictEqual(parsePointer('/~01'), ['~1']);
  });

  test('no unicode normalization', () => {
    assert.deepStrictEqual(parsePointer('/é'), ['é']);
    assert.notDeepStrictEqual(parsePointer('/é'), ['é']);
  });
});

describe('parsePointer invalid', () => {
  for (const input of ['/~~01', '/~', '/a~', '/~2', '/~a', 'a', ' /a', '#/a']) {
    test(`rejects ${JSON.stringify(input)}`, () => {
      assert.throws(() => parsePointer(input), invalid);
    });
  }

  test('error is a SyntaxError exactly', () => {
    try {
      parsePointer('a');
      assert.fail('should throw');
    } catch (err) {
      assert.ok(err instanceof SyntaxError);
      assert.strictEqual(err.constructor, SyntaxError);
      assert.strictEqual(err.message, 'invalid pointer');
    }
  });
});

describe('parsePointer input type and freshness', () => {
  const inputs = [
    ['number', 1],
    ['null', null],
    ['undefined', undefined],
    ['array', ['/a']],
    ['object', { a: 1 }],
    ['String object', new String('/a')],
  ];
  for (const [label, input] of inputs) {
    test(`rejects ${label}`, () => {
      assert.throws(() => parsePointer(input), {
        name: 'TypeError',
        message: 'pointer must be a string',
      });
      try {
        parsePointer(input);
      } catch (err) {
        assert.ok(err instanceof TypeError);
        assert.strictEqual(err.constructor, TypeError);
      }
    });
  }

  test('returns a new array each call', () => {
    const a = parsePointer('/a/b');
    const b = parsePointer('/a/b');
    assert.notStrictEqual(a, b);
    assert.deepStrictEqual(a, b);
  });

  test('mutating result does not affect later calls', () => {
    const a = parsePointer('/a/b');
    a.push('x');
    a[0] = 'changed';
    assert.deepStrictEqual(parsePointer('/a/b'), ['a', 'b']);
    const e = parsePointer('');
    e.push('x');
    assert.deepStrictEqual(parsePointer(''), []);
  });
});

describe('following: object members', () => {
  for (const name of ['toString', 'constructor', '__proto__', 'hasOwnProperty']) {
    test(`inherited name ${name} is not found`, () => {
