import { test } from 'node:test';
import assert from 'node:assert/strict';
import { applyPatch, PatchError } from '../jsonpatch.mjs';

function expectPatchError(doc, patch, message, index) {
  assert.equal(Object.getPrototypeOf(PatchError.prototype), Error.prototype);
  assert.throws(() => applyPatch(doc, patch), (err) => {
    assert.ok(err instanceof PatchError);
    assert.equal(err.name, 'PatchError');
    assert.equal(err.message, message);
    assert.equal(err.index, index);
    return true;
  });
}

function expectOp(op, reason, doc = {}) {
  expectPatchError(doc, [op], `operation 0: ${reason}`, 0);
}

function withProto(proto, own = {}) {
  return Object.assign(Object.create(proto), own);
}

test('patch must be an array', () => {
  const notArrays = [
    undefined, null, {}, '[]', {length: 0}, new Uint8Array(0), 5, true,
